"""Which files to skip, and which findings the user has accepted.

Inside a git repo we ask git itself which files are ignored, so `.gitignore`
is honoured exactly rather than reimplemented. `.secsentryignore` adds
scanner-only patterns on top, and the allowlist suppresses findings by
fingerprint — never by storing the secret.
"""

from __future__ import annotations

import fnmatch
from pathlib import Path

from secsentry.git.run import git

SKIP_DIRS = {
    ".git",
    "node_modules",
    ".venv",
    "venv",
    "__pycache__",
    "dist",
    "build",
    ".mypy_cache",
    ".pytest_cache",
    ".ruff_cache",
    ".secsentry",
}

IGNORE_FILE = ".secsentryignore"
ALLOWLIST_FILE = ".secsentryallow"


def _read_patterns(path: Path) -> list[str]:
    if not path.is_file():
        return []
    out = []
    for raw in path.read_text(encoding="utf-8", errors="replace").splitlines():
        line = raw.strip()
        if line and not line.startswith("#"):
            out.append(line)
    return out


class Ignores:
    def __init__(self, repo: Path) -> None:
        self.patterns = _read_patterns(repo / IGNORE_FILE)

    def match(self, rel: str) -> bool:
        rel = rel.replace("\\", "/")
        for pat in self.patterns:
            if fnmatch.fnmatch(rel, pat) or fnmatch.fnmatch(Path(rel).name, pat):
                return True
            if pat.endswith("/") and rel.startswith(pat):
                return True
        return False


def load_allowlist(repo: Path) -> set[str]:
    """Accepted findings, identified by SHA-256 fingerprint prefix."""
    return {p.split()[0].lower() for p in _read_patterns(repo / ALLOWLIST_FILE)}


def is_allowlisted(fingerprint: str, allowed: set[str]) -> bool:
    return any(fingerprint.startswith(a) for a in allowed if a)


def git_tracked_files(repo: Path) -> list[str] | None:
    """Files git would show: tracked plus untracked, minus everything ignored."""
    try:
        out = git(repo, "ls-files", "--cached", "--others", "--exclude-standard")
    except Exception:
        return None
    return [line for line in out.splitlines() if line.strip()]

"""Walk candidate files: skip junk dirs, ignored paths, and binaries."""

from __future__ import annotations

from pathlib import Path

from secsentry.git.blobs import is_git_repo
from secsentry.scan.ignore import SKIP_DIRS, Ignores, git_tracked_files

MAX_FILE_BYTES = 1_000_000


def _readable_text(path: Path) -> tuple[str, bytes] | None:
    try:
        if path.stat().st_size > MAX_FILE_BYTES:
            return None
        data = path.read_bytes()
    except OSError:
        return None
    if b"\0" in data[:8192]:
        return None
    try:
        return data.decode("utf-8"), data
    except UnicodeDecodeError:
        return None


def _candidate_paths(root: Path) -> list[str]:
    if is_git_repo(root):
        tracked = git_tracked_files(root)
        if tracked is not None:
            return tracked
    out = []
    for path in root.rglob("*"):
        if path.is_file() and not any(part in SKIP_DIRS for part in path.parts):
            out.append(str(path.relative_to(root)))
    return out


def iter_text_files(root: Path):
    root = root.resolve()
    ignores = Ignores(root)
    for rel in _candidate_paths(root):
        if any(part in SKIP_DIRS for part in Path(rel).parts):
            continue
        if ignores.match(rel):
            continue
        got = _readable_text(root / rel)
        if got is None:
            continue
        text, data = got
        yield rel, text, data

"""Orchestrate detectors → structural verify → classify → aggregate."""

from __future__ import annotations

from dataclasses import dataclass, field
from pathlib import Path

from secsentry.classify.heuristic import classify
from secsentry.detectors.registry import detect
from secsentry.git.blobs import is_git_repo
from secsentry.git.run import git
from secsentry.models import Finding, fingerprint, mask_secret
from secsentry.scan.aggregate import Secret, group, rank
from secsentry.scan.ignore import is_allowlisted, load_allowlist
from secsentry.scan.staged import staged_text
from secsentry.scan.working_tree import iter_text_files
from secsentry.verify.structural import structural_ok

SEVERITY_RANK = {"low": 1, "medium": 2, "high": 3, "critical": 4}


@dataclass
class ScanReport:
    findings: list[Finding] = field(default_factory=list)
    files_scanned: int = 0
    blobs_scanned: int = 0
    commits_scanned: int = 0
    repo: str = ""
    allowlisted: int = 0

    @property
    def secrets(self) -> list[Secret]:
        return group(self.findings)

    def counts(self) -> dict[str, int]:
        out = {"critical": 0, "high": 0, "medium": 0, "low": 0}
        for s in self.secrets:
            key = s.severity.lower()
            if key in out:
                out[key] += 1
        return out

    def should_fail(self, fail_on: str) -> bool:
        threshold = SEVERITY_RANK.get(fail_on.lower(), 3)
        return any(rank(f.severity) >= threshold for f in self.findings)


@dataclass
class ScanContext:
    findings: list[Finding] = field(default_factory=list)
    seen_fp_path: set[tuple[str, str, int]] = field(default_factory=set)
    head_blob_oids: set[str] = field(default_factory=set)
    allowed: set[str] = field(default_factory=set)
    files_scanned: int = 0
    blobs_scanned: int = 0
    commits_scanned: int = 0
    allowlisted: int = 0

    def add_occurrence(self, base: Finding, **kwargs) -> None:
        f = Finding(**{**base.__dict__, **kwargs})
        if is_allowlisted(f.fingerprint, self.allowed):
            self.allowlisted += 1
            return
        key = (f.fingerprint, f.path, f.line)
        if key in self.seen_fp_path:
            return
        self.seen_fp_path.add(key)
        self.findings.append(f)


def findings_from_text(
    ctx: ScanContext,
    *,
    path: str,
    text: str,
    blob_oid: str = "",
) -> list[Finding]:
    found: list[Finding] = []
    for hit in detect(text, path):
        ok = structural_ok(hit.secret_type, hit.secret)
        decision = classify(path=path, secret_type=hit.secret_type, secret=hit.secret, structural=ok)
        if not decision.keep:
            continue
        found.append(
            Finding(
                secret_type=hit.secret_type,
                severity=hit.severity,
                confidence=decision.confidence,
                path=path,
                line=hit.line,
                column=hit.column,
                masked=mask_secret(hit.secret),
                fingerprint=fingerprint(hit.secret),
                blob_oid=blob_oid,
                structural_ok=ok,
                entropy=hit.entropy,
                why=decision.why,
            )
        )
    return found


def _head_blob_oids(repo: Path) -> set[str]:
    oids: set[str] = set()
    try:
        for line in git(repo, "ls-tree", "-r", "--full-tree", "HEAD").splitlines():
            meta, _, _path = line.partition("\t")
            bits = meta.split()
            if len(bits) >= 3 and bits[1] == "blob":
                oids.add(bits[2])
    except Exception:
        pass
    return oids


def run_scan(
    repo: Path,
    *,
    history: bool = False,
    staged: bool = False,
    severity: str | None = None,
    types: list[str] | None = None,
) -> ScanReport:
    repo = repo.resolve()
    ctx = ScanContext(allowed=load_allowlist(repo))

    if staged:
        for path, text in staged_text(repo):
            ctx.files_scanned += 1
            for f in findings_from_text(ctx, path=path, text=text):
                ctx.add_occurrence(f, source="staged")
    else:
        for rel, text, _data in iter_text_files(repo):
            ctx.files_scanned += 1
            for f in findings_from_text(ctx, path=rel, text=text):
                ctx.add_occurrence(f, source="working-tree")

        if history and is_git_repo(repo):
            ctx.head_blob_oids = _head_blob_oids(repo)
            from secsentry.scan.history import scan_history

            scan_history(ctx, repo)
            for f in ctx.findings:
                if f.blob_oid:
                    f.still_in_head = f.blob_oid in ctx.head_blob_oids

    findings = ctx.findings
    if severity:
        threshold = SEVERITY_RANK.get(severity.lower(), 0)
        findings = [f for f in findings if rank(f.severity) >= threshold]
    if types:
        wanted = [t.lower() for t in types]
        findings = [f for f in findings if any(w in f.secret_type.lower() for w in wanted)]

    return ScanReport(
        findings=findings,
        files_scanned=ctx.files_scanned,
        blobs_scanned=ctx.blobs_scanned,
        commits_scanned=ctx.commits_scanned,
        repo=str(repo),
        allowlisted=ctx.allowlisted,
    )

