def git_bytes(repo: Path, *args: str, check: bool = True) -> bytes:
    """Read raw git output. Needed for zip/tar blobs that are not UTF-8."""
    proc = subprocess.run(
        ["git", "-C", str(repo), *args],
        capture_output=True,
    )
    if check and proc.returncode != 0:
        err = proc.stderr.decode("utf-8", errors="replace").strip()
        raise GitError(err or f"git {' '.join(args)} failed")
    return proc.stdout

