"""Unwrap encoded secrets sitting in otherwise-boring text.

A key pasted as `echo KEY | base64` is invisible to a regex that only looks at
the stored bytes. We peel base64, hex, and percent-encoding locally — no
network — then run the same detectors on the decoded text.

Depth is capped because people nest encodings, and because unbounded decode
turns every lockfile hash into a CPU sink.
"""

from __future__ import annotations

import base64
import binascii
import re
from dataclasses import dataclass
from urllib.parse import unquote_to_bytes

MAX_DECODE_DEPTH = 3
MAX_DECODED_BYTES = 64_000

# Long enough that random tokens in JSON rarely qualify; short enough to catch
# a 20-char AWS key after base64 (~28 chars).
_B64 = re.compile(r"(?<![A-Za-z0-9+/=])[A-Za-z0-9+/]{20,}={0,2}(?![A-Za-z0-9+/=])")
_B64URL = re.compile(r"(?<![A-Za-z0-9_-])[A-Za-z0-9_-]{20,}={0,2}(?![A-Za-z0-9_-])")
_HEX = re.compile(r"(?<![0-9A-Fa-f])(?:0x)?([0-9A-Fa-f]{32,})(?![0-9A-Fa-f])")
_PCT = re.compile(r"(?:%[0-9A-Fa-f]{2}){8,}")


@dataclass(frozen=True)
class DecodedChunk:
    text: str
    encodings: tuple[str, ...]
    line: int
    column: int


def _printable_text(raw: bytes) -> str | None:
    if not raw or len(raw) > MAX_DECODED_BYTES or b"\x00" in raw[:4096]:
        return None
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        try:
            text = raw.decode("ascii")
        except UnicodeDecodeError:
            return None
    if not text.strip() or not any(ch.isprintable() or ch in "\n\t\r" for ch in text):
        return None
    # Reject binary-as-latin1: too many control characters.
    controls = sum(1 for ch in text if ord(ch) < 32 and ch not in "\n\t\r")
    if controls / max(len(text), 1) > 0.05:
        return None
    return text


def _b64(token: str) -> str | None:
    pad = "=" * (-len(token) % 4)
    for decoder in (base64.b64decode, base64.urlsafe_b64decode):
        try:
            raw = decoder(token + pad, validate=False)
        except (binascii.Error, ValueError):
            continue
        text = _printable_text(raw)
        if text and text != token:
            return text
    return None


def _hex(token: str) -> str | None:
    body = token[2:] if token.lower().startswith("0x") else token
    if len(body) % 2:
        return None
    try:
        raw = bytes.fromhex(body)
    except ValueError:
        return None
    return _printable_text(raw)


def _pct(token: str) -> str | None:
    try:
        raw = unquote_to_bytes(token)
    except Exception:
        return None
    return _printable_text(raw)


def _candidates(line: str) -> list[tuple[str, str, int]]:
    """(kind, token, column) unique by token start."""
    found: list[tuple[str, str, int]] = []
    seen: set[tuple[int, str]] = set()
    for kind, cre, group in (
        ("base64", _B64, 0),
        ("base64", _B64URL, 0),
        ("hex", _HEX, 1),
        ("percent", _PCT, 0),
    ):
        for m in cre.finditer(line):
            token = m.group(group)
            col = m.start(group) + 1
            key = (col, token)
            if key in seen:
                continue
            seen.add(key)
            found.append((kind, token, col))
    return found


def iter_decoded(text: str, *, max_depth: int = MAX_DECODE_DEPTH) -> list[DecodedChunk]:
    """All decoded layers under `text`, with the original line/column of the wrapper."""
    out: list[DecodedChunk] = []
    if max_depth <= 0 or not text:
        return out

    queue: list[tuple[str, tuple[str, ...], int, int]] = []
    for i, line in enumerate(text.splitlines(), start=1):
        for kind, token, col in _candidates(line):
            decoded = {"base64": _b64, "hex": _hex, "percent": _pct}[kind](token)
            if decoded:
                queue.append((decoded, (kind,), i, col))

    seen_text: set[str] = set()
    while queue:
        payload, chain, line, col = queue.pop(0)
        if payload in seen_text or len(chain) > max_depth:
            continue
        seen_text.add(payload)
        out.append(DecodedChunk(payload, chain, line, col))
        if len(chain) >= max_depth:
            continue
        for kind, token, _c in _candidates(payload):
            decoded = {"base64": _b64, "hex": _hex, "percent": _pct}[kind](token)
            if decoded and decoded not in seen_text:
                queue.append((decoded, chain + (kind,), line, col))
    return out

"""Open zip / tar / gzip and yield inner text files.

Git stores an archive as one blob. A scanner that only reads UTF-8 therefore
never sees `deploy.zip!secrets/.env`. We unpack locally, depth-limited, and
report the inner path with `!` so the leak location stays clickable.
"""

from __future__ import annotations

import gzip
import io
import tarfile
import zipfile
from pathlib import Path

MAX_ARCHIVE_BYTES = 8_000_000
MAX_MEMBER_BYTES = 1_000_000
MAX_ARCHIVE_DEPTH = 2
MAX_MEMBERS = 80

ARCHIVE_SUFFIXES = {".zip", ".whl", ".jar", ".tar", ".tgz", ".gz", ".taz"}


def looks_like_archive(name: str, data: bytes) -> bool:
    if len(data) < 4 or len(data) > MAX_ARCHIVE_BYTES:
        return False
    suffix = Path(name).suffix.lower()
    if suffix in {".tar"} or name.lower().endswith((".tar.gz", ".tgz")):
        return True
    if data[:2] == b"PK":
        return True
    if data[:2] == b"\x1f\x8b":
        return True
    if suffix in ARCHIVE_SUFFIXES:
        return True
    return False


def _utf8(data: bytes) -> str | None:
    if not data or len(data) > MAX_MEMBER_BYTES or b"\x00" in data[:8192]:
        return None
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        return None


def _walk(data: bytes, name: str, depth: int) -> list[tuple[str, str]]:
    if depth > MAX_ARCHIVE_DEPTH or not looks_like_archive(name, data):
        return []

    found: list[tuple[str, str]] = []

    def add(inner_name: str, payload: bytes) -> None:
        if len(found) >= MAX_MEMBERS:
            return
        label = f"{name}!{inner_name}"
        text = _utf8(payload)
        if text is not None:
            found.append((label, text))
        elif looks_like_archive(inner_name, payload):
            found.extend(_walk(payload, label, depth + 1))

    bio = io.BytesIO(data)
    if data[:2] == b"PK" or name.lower().endswith((".zip", ".whl", ".jar")):
        try:
            with zipfile.ZipFile(bio) as zf:
                for info in zf.infolist()[:MAX_MEMBERS]:
                    if info.is_dir() or info.file_size > MAX_MEMBER_BYTES:
                        continue
                    try:
                        add(info.filename, zf.read(info))
                    except Exception:
                        continue
            return found
        except zipfile.BadZipFile:
            return found

    if data[:2] == b"\x1f\x8b" or name.lower().endswith((".gz", ".tgz", ".tar.gz")):
        try:
            unpacked = gzip.decompress(data)
        except Exception:
            return found
        if tarfile.is_tarfile(io.BytesIO(unpacked)):
            return _walk(unpacked, name, depth)
        text = _utf8(unpacked)
        if text is not None:
            found.append((f"{name}!(decompressed)", text))
        return found

    try:
        with tarfile.open(fileobj=bio, mode="r:*") as tf:
            for member in tf.getmembers()[:MAX_MEMBERS]:
                if not member.isfile() or member.size > MAX_MEMBER_BYTES:
                    continue
                extracted = tf.extractfile(member)
                if extracted is None:
                    continue
                try:
                    add(member.name, extracted.read())
                except Exception:
                    continue
    except tarfile.TarError:
        return found
    return found


def iter_archive_texts(data: bytes, name: str) -> list[tuple[str, str]]:
    """Return (archive!inner/path, text) for each readable member."""
    return _walk(data, name, 1)

"""Walk candidate files: skip junk dirs, ignored paths, and binaries.

Archives are opened (zip / tar / gz). Inner text files are yielded as
`archive.zip!path/inside` so the leak location stays a real path.
"""

from __future__ import annotations

from pathlib import Path

from secsentry.git.blobs import is_git_repo
from secsentry.scan.archives import MAX_ARCHIVE_BYTES, iter_archive_texts, looks_like_archive
from secsentry.scan.ignore import SKIP_DIRS, Ignores, git_tracked_files

MAX_FILE_BYTES = 1_000_000


def _read_bytes(path: Path, limit: int) -> bytes | None:
    try:
        if path.stat().st_size > limit:
            return None
        return path.read_bytes()
    except OSError:
        return None


def _as_text(data: bytes) -> str | None:
    if b"\x00" in data[:8192]:
        return None
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        return None


def _candidate_paths(root: Path) -> list[str]:
    if is_git_repo(root):
        tracked = git_tracked_files(root)
        if tracked is not None:
            return tracked
    out = []
    for path in root.rglob("*"):
        if path.is_file() and not any(part in SKIP_DIRS for part in path.parts):
            out.append(str(path.relative_to(root)))
    return out


def iter_text_files(root: Path):
    root = root.resolve()
    ignores = Ignores(root)
    for rel in _candidate_paths(root):
        if any(part in SKIP_DIRS for part in Path(rel).parts):
            continue
        if ignores.match(rel):
            continue
        path = root / rel
        # Read enough to decide archive vs text. Archives may be larger.
        data = _read_bytes(path, MAX_ARCHIVE_BYTES)
        if data is None:
            data = _read_bytes(path, MAX_FILE_BYTES)
        if data is None:
            continue
        if looks_like_archive(rel, data):
            for inner, text in iter_archive_texts(data, rel):
                yield inner, text, data
            continue
        if len(data) > MAX_FILE_BYTES:
            continue
        text = _as_text(data)
        if text is None:
            continue
        yield rel, text, data

