"""Git history scan using unique blob OIDs."""

from __future__ import annotations

from pathlib import Path

from secsentry.git.blobs import unique_blobs_for_history
from secsentry.scan.archives import iter_archive_texts, looks_like_archive
from secsentry.scan.engine import ScanContext, findings_from_text


def _hits_for_blob(ctx: ScanContext, oid: str, data: bytes, name: str) -> list:
    hits = []
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError:
        text = None
    if text is not None and b"\x00" not in data[:8192]:
        hits.extend(findings_from_text(ctx, path=name, text=text, blob_oid=oid))
    if looks_like_archive(name, data):
        for inner, inner_text in iter_archive_texts(data, name):
            hits.extend(findings_from_text(ctx, path=inner, text=inner_text, blob_oid=oid))
    return hits


def scan_history(ctx: ScanContext, repo: Path) -> None:
    contents, refs = unique_blobs_for_history(repo)
    blob_hits: dict[str, list] = {}
    ctx.blobs_scanned += len(contents)
    ctx.commits_scanned += len({r.commit for r in refs})
    for oid, data in contents.items():
        blob_hits[oid] = _hits_for_blob(ctx, oid, data, "(blob)")

    for ref in refs:
        for f in blob_hits.get(ref.oid, []):
            # Archive members were scanned as "(blob)!inner". Rewrite to the
            # real git path so the case file points at deploy.zip!secrets/.env.
            path = f.path
            if path.startswith("(blob)!"):
                path = f"{ref.path}!{path.split('!', 1)[1]}"
            elif path == "(blob)":
                path = ref.path
            ctx.add_occurrence(
                f,
                path=path,
                commit=ref.commit,
                author=ref.author,
                author_email=ref.author_email,
                timestamp=ref.timestamp,
                source="history",
            )

