	add("pypi_token", "HIGH", `\bpypi-AgEIcHlwaS[0-9A-Za-z\-_]{50,}\b`, 0, "pypi-")
	add("private_key", "CRITICAL", `-----BEGIN (?:RSA |EC |OPENSSH |DSA )?PRIVATE KEY-----`, 0, "BEGIN", "PRIVATE KEY")
	add("jwt", "MEDIUM", `\beyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\b`, 0, "eyJ")
	add("generic_api_key", "MEDIUM", `(?i)(?:api[_-]?key|secret[_-]?key|access[_-]?token)\s*[:=]\s*['"]([A-Za-z0-9_\-./+=]{20,})['"]`, 1, "api_key", "secret_key", "access_token")
	add("db_url", "HIGH", `(?i)\b(?:postgres|mysql|mongodb(?:\+srv)?)://[^\s'"]+:[^\s'"]+@[^\s'"]+`, 0, "postgres://", "mysql://", "mongodb")
}

func HasKeyword(text string) bool {
	low := strings.ToLower(text)
	for _, k := range Keywords {
		if strings.Contains(low, k) {
			return true
		}
	}
	return false
}

func Shannon(s string) float64 {
	if s == "" {
		return 0
	}
	freq := map[rune]int{}
	for _, r := range s {
		freq[r]++
	}
	n := float64(utf8.RuneCountInString(s))
	var h float64
	for _, c := range freq {
		p := float64(c) / n
		h -= p * math.Log2(p)
	}
	return h
}

func Detect(text string) []Hit {
	if !HasKeyword(text) {
		return nil
	}
	var hits []Hit
	for i, line := range strings.Split(text, "\n") {
		low := strings.ToLower(line)
		if strings.Contains(line, "AKIAEXAMPLEFAKEKEYZZZZ") {
			continue
		}
		for _, r := range rules {
			ok := false
			for _, k := range r.keys {
				if strings.Contains(low, strings.ToLower(k)) {
					ok = true
					break
				}
			}
			if !ok {
				continue
			}
			for _, m := range r.re.FindAllStringSubmatchIndex(line, -1) {
				secret := line[m[0]:m[1]]
				if r.capture > 0 && len(m) >= (r.capture+1)*2 {
					secret = line[m[r.capture*2]:m[r.capture*2+1]]
				}
				sl := strings.ToLower(secret)
				if strings.Contains(sl, "example") || strings.Contains(sl, "placeholder") ||
					strings.Contains(sl, "changeme") || strings.Contains(sl, "your-") {
					continue
				}
				col := utf8.RuneCountInString(line[:m[0]]) + 1
				hits = append(hits, Hit{
					Type: r.id, Severity: r.sev, Secret: secret,
					Line: i + 1, Column: col, Entropy: Shannon(secret),
				})
			}
		}
	}
	return hits
}

package verify

import (
	"encoding/base64"
	"encoding/json"
	"regexp"
	"strings"
)

var (
	reAWS     = regexp.MustCompile(`^AKIA[0-9A-Z]{16}$`)
	reShopify = regexp.MustCompile(`^shp(?:ss|at|ca|pa)_[0-9a-fA-F]{32}$`)
	reTwilio  = regexp.MustCompile(`^SK[0-9a-fA-F]{32}$`)
)

func OK(secretType, secret string) bool {
	switch {
	case secretType == "aws_access_key":
		return reAWS.MatchString(secret)
	case secretType == "github_pat" || secretType == "github_oauth" || secretType == "github_user" ||
		secretType == "github_server" || secretType == "github_refresh":
		return strings.HasPrefix(secret, "gh") && len(secret) == 40
	case strings.HasPrefix(secretType, "openai"):
		return strings.Contains(secret, "T3BlbkFJ")
	case strings.HasPrefix(secretType, "anthropic"):
		return strings.HasPrefix(secret, "sk-ant-") && len(secret) > 40
	case secretType == "jwt":
		return jwtOK(secret)
	case secretType == "private_key":
		return strings.Contains(secret, "BEGIN") && strings.Contains(secret, "PRIVATE KEY")
	case secretType == "google_api_key":
		return strings.HasPrefix(secret, "AIza") && len(secret) == 39
	case secretType == "stripe_live":
		return strings.HasPrefix(secret, "sk_live_") && len(secret) >= 32
	case secretType == "shopify_token":
		return reShopify.MatchString(secret)
	case secretType == "sendgrid_key":
		return strings.HasPrefix(secret, "SG.") && strings.Count(secret, ".") == 2
	case secretType == "twilio_key":
		return reTwilio.MatchString(secret)
	case secretType == "npm_token":
		return strings.HasPrefix(secret, "npm_") && len(secret) == 40
	default:
		return true
	}
}

func jwtOK(secret string) bool {
	parts := strings.Split(secret, ".")
	if len(parts) != 3 {
		return false
	}
	raw, err := base64.RawURLEncoding.DecodeString(parts[0])
	if err != nil {
		pad := parts[0] + strings.Repeat("=", (4-len(parts[0])%4)%4)
		raw, err = base64.URLEncoding.DecodeString(pad)
		if err != nil {
			return false
		}
	}
	var header map[string]any
	if json.Unmarshal(raw, &header) != nil {
		return false
	}
	_, ok := header["alg"]
	return ok
}

package classify

import "unicode"

// Local BPE-style rarity. English merges collapse common pairs; a password
// or API key stays as many short tokens. tokens/runes is high for secrets
// and low for "password" / "example". No network, no vendor model.
var merges = []string{
	"th", "he", "in", "er", "an", "re", "on", "at", "en", "nd",
	"ti", "es", "or", "te", "of", "ed", "is", "it", "al", "ar",
	"st", "to", "nt", "ng", "se", "ha", "as", "ou", "io", "le",
	"ve", "co", "me", "de", "hi", "ri", "ro", "ic", "ne", "ea",
	"ra", "ce", "li", "ch", "ll", "be", "ma", "si", "om", "ur",
	"the", "ing", "and", "ion", "ent", "her", "for", "tha", "ter",
	"res", "con", "all", "ers", "ate", "ver", "pro", "ted", "ess",
	"key", "api", "tok", "sec", "pass", "word", "user", "name",
	"example", "placeholder", "changeme", "password", "secret",
}

func Rarity(s string) float64 {
	if s == "" {
		return 0
	}
	runes := []rune(s)
	n := float64(len(runes))
	low := make([]rune, len(runes))
	for i, r := range runes {
		low[i] = unicode.ToLower(r)
	}
	text := string(low)
	tokens := 0
	i := 0
	for i < len(text) {
		matched := 1
		for _, m := range merges {
			if len(m) > matched && i+len(m) <= len(text) && text[i:i+len(m)] == m {
				matched = len(m)
			}
		}
		tokens++
		i += matched
	}
	return float64(tokens) / n
}

package classify

import (
	"fmt"
	"strings"

	"github.com/umeraamir69/secsentry/internal/detect"
)

type Decision struct {
	Keep       bool
	Confidence float64
	Why        []string
}

func Classify(path, secretType, secret string, structural bool) Decision {
	why := []string{"rule=" + secretType}
	conf := 0.55
	low := strings.ToLower(strings.ReplaceAll(path, "\\", "/"))

	if structural {
		conf += 0.2
		why = append(why, "structural_ok")
	}
	ent := detect.Shannon(secret)
	why = append(why, fmt.Sprintf("entropy=%.2f", ent))
	if ent >= 3.5 {
		conf += 0.1
	}

	rar := Rarity(secret)
	why = append(why, fmt.Sprintf("bpe_rarity=%.2f", rar))
	if rar >= 0.55 {
		conf += 0.08
	} else if rar < 0.35 && secretType == "generic_api_key" {
		conf -= 0.25
		why = append(why, "english_like")
	}

	for _, lock := range []string{"package-lock.json", "yarn.lock", "pnpm-lock.yaml", "poetry.lock"} {
		if strings.HasSuffix(low, lock) || strings.Contains(low, lock) {
			return Decision{false, 0.1, append(why, "lockfile")}
		}
	}
	if secretType == "generic_api_key" {
		for _, p := range []string{".md", "docs/", "test/", "tests/", "example"} {
			if strings.Contains(low, p) {
				conf -= 0.25
				why = append(why, "docs_or_tests")
				break
			}
		}
	}
	keep := conf >= 0.5
	if (secretType == "private_key" || secretType == "aws_access_key") && structural {
		keep = true
		if conf < 0.9 {
			conf = 0.9
		}
	}
	if conf > 0.99 {
		conf = 0.99
	}
	return Decision{keep, conf, why}
}

package gitutil

import (
	"bytes"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

func Run(repo string, args ...string) (string, error) {
	cmd := exec.Command("git", append([]string{"-C", repo}, args...)...)
	var out, errb bytes.Buffer
	cmd.Stdout = &out
	cmd.Stderr = &errb
	if err := cmd.Run(); err != nil {
		return "", err
	}
	return out.String(), nil
}

func RunBytes(repo string, args ...string) ([]byte, error) {
	cmd := exec.Command("git", append([]string{"-C", repo}, args...)...)
	return cmd.Output()
}

func IsRepo(path string) bool {
	st, err := os.Stat(filepath.Join(path, ".git"))
	return err == nil && (st.IsDir() || st.Mode().IsRegular())
}

func TrackedFiles(repo string) ([]string, error) {
	out, err := Run(repo, "ls-files", "--cached", "--others", "--exclude-standard")
	if err != nil {
		return nil, err
	}
	var files []string
	for _, line := range strings.Split(out, "\n") {
		line = strings.TrimSpace(line)
		if line != "" {
			files = append(files, line)
		}
	}
	return files, nil
}

type BlobRef struct {
	OID, Path, Commit, Author, Email, Timestamp string
}

func UniqueBlobs(repo string) (map[string][]byte, []BlobRef, error) {
	log, err := Run(repo, "log", "--all", "--format=%H%x00%an%x00%ae%x00%aI")
	if err != nil {
		return nil, nil, err
	}
	contents := map[string][]byte{}
	var refs []BlobRef
	for _, block := range strings.Split(log, "\n") {
		if strings.TrimSpace(block) == "" {
			continue
		}
		p := strings.Split(block, "\x00")
		if len(p) < 4 {
			continue
		}
		sha, author, email, ts := p[0], p[1], p[2], p[3]
		tree, err := Run(repo, "ls-tree", "-r", "--full-tree", sha)
		if err != nil {
			continue
		}
		for _, line := range strings.Split(tree, "\n") {
			meta, path, ok := strings.Cut(line, "\t")
			if !ok {
				continue
			}
			bits := strings.Fields(meta)
			if len(bits) < 3 || bits[1] != "blob" {
				continue
			}
			oid := bits[2]
			refs = append(refs, BlobRef{oid, path, sha, author, email, ts})
			if _, seen := contents[oid]; !seen {
				raw, err := RunBytes(repo, "cat-file", "blob", oid)
				if err != nil {
					continue
				}
				contents[oid] = raw
			}
		}
	}
	return contents, refs, nil
}

func HeadBlobOIDs(repo string) map[string]struct{} {
	out := map[string]struct{}{}
	tree, err := Run(repo, "ls-tree", "-r", "--full-tree", "HEAD")
	if err != nil {
		return out
	}
	for _, line := range strings.Split(tree, "\n") {
		meta, _, ok := strings.Cut(line, "\t")
		if !ok {
			continue
		}
		bits := strings.Fields(meta)
		if len(bits) >= 3 && bits[1] == "blob" {
			out[bits[2]] = struct{}{}
		}
	}
	return out
}

func Staged(repo string) ([][2]string, error) {
	names, err := Run(repo, "diff", "--cached", "--name-only", "--diff-filter=ACMR")
	if err != nil {
		return nil, err
	}
	var pairs [][2]string
	for _, name := range strings.Split(names, "\n") {
		name = strings.TrimSpace(name)
		if name == "" {
			continue
		}
		blob, err := Run(repo, "show", ":"+name)
		if err != nil {
			continue
		}
		pairs = append(pairs, [2]string{name, blob})
	}
	return pairs, nil
}

package scan

import (
	"encoding/base64"
	"encoding/hex"
	"net/url"
	"regexp"
	"strings"
	"unicode/utf8"
)

const maxDecodeDepth = 3
const maxDecoded = 64000

var (
	reB64    = regexp.MustCompile(`[A-Za-z0-9+/]{20,}={0,2}`)
	reB64URL = regexp.MustCompile(`[A-Za-z0-9_-]{20,}={0,2}`)
	reHex    = regexp.MustCompile(`(?:0x)?([0-9A-Fa-f]{32,})`)
	rePct    = regexp.MustCompile(`(?:%[0-9A-Fa-f]{2}){8,}`)
)

type decodedChunk struct {
	Text       string
	Encodings  []string
	Line, Col  int
}

func printable(raw []byte) string {
	if len(raw) == 0 || len(raw) > maxDecoded || bytesContainNUL(raw) {
		return ""
	}
	if !utf8.Valid(raw) {
		return ""
	}
	s := string(raw)
	ctrl := 0
	for _, r := range s {
		if r < 32 && r != '\n' && r != '\t' && r != '\r' {
			ctrl++
		}
	}
	if float64(ctrl)/float64(len(s)+1) > 0.05 {
		return ""
	}
	return s
}

func bytesContainNUL(b []byte) bool {
	n := len(b)
	if n > 4096 {
		n = 4096
	}
	for _, c := range b[:n] {
		if c == 0 {
			return true
		}
	}
	return false
}

func tryB64(token string) string {
	pad := strings.Repeat("=", (4-len(token)%4)%4)
	blob := token + pad
	if raw, err := base64.StdEncoding.DecodeString(blob); err == nil {
		if t := printable(raw); t != "" && t != token {
			return t
		}
	}
	if raw, err := base64.URLEncoding.DecodeString(blob); err == nil {
		if t := printable(raw); t != "" && t != token {
			return t
		}
	}
	return ""
}

func tryHex(token string) string {
	body := token
	if strings.HasPrefix(strings.ToLower(body), "0x") {
		body = body[2:]
	}
	if len(body)%2 == 1 {
		return ""
	}
	raw, err := hex.DecodeString(body)
	if err != nil {
		return ""
	}
	return printable(raw)
}

func tryPct(token string) string {
	raw, err := url.QueryUnescape(token)
	if err != nil {
		return ""
	}
	return printable([]byte(raw))
}

func iterDecoded(text string) []decodedChunk {
	type item struct {
		payload string
		chain   []string
		line    int
		col     int
	}
	var queue []item
	for i, line := range strings.Split(text, "\n") {
		for _, m := range reB64.FindAllStringIndex(line, -1) {
			tok := line[m[0]:m[1]]
			if d := tryB64(tok); d != "" {
				queue = append(queue, item{d, []string{"base64"}, i + 1, utf8.RuneCountInString(line[:m[0]]) + 1})
			}
		}
		for _, m := range reHex.FindAllStringSubmatchIndex(line, -1) {
			if len(m) < 4 {
				continue
			}
			tok := line[m[2]:m[3]]
			if d := tryHex(tok); d != "" {
				queue = append(queue, item{d, []string{"hex"}, i + 1, utf8.RuneCountInString(line[:m[2]]) + 1})
			}
		}
		for _, m := range rePct.FindAllStringIndex(line, -1) {
			tok := line[m[0]:m[1]]
			if d := tryPct(tok); d != "" {
				queue = append(queue, item{d, []string{"percent"}, i + 1, utf8.RuneCountInString(line[:m[0]]) + 1})
			}
		}
		_ = reB64URL
	}
	seen := map[string]bool{}
	var out []decodedChunk
	for len(queue) > 0 {
		it := queue[0]
		queue = queue[1:]
		if seen[it.payload] || len(it.chain) > maxDecodeDepth {
			continue
		}
		seen[it.payload] = true
		out = append(out, decodedChunk{it.payload, it.chain, it.line, it.col})
		if len(it.chain) >= maxDecodeDepth {
			continue
		}
		for _, m := range reB64.FindAllString(it.payload, -1) {
			if d := tryB64(m); d != "" && !seen[d] {
				queue = append(queue, item{d, append(append([]string{}, it.chain...), "base64"), it.line, it.col})
			}
		}
	}
	return out
}

package scan

import (
	"archive/tar"
	"archive/zip"
	"bytes"
	"compress/gzip"
	"io"
	"path/filepath"
	"strings"
	"unicode/utf8"
)

const (
	maxArchiveBytes = 8_000_000
	maxMemberBytes  = 1_000_000
	maxArchiveDepth = 2
	maxMembers      = 80
)

func looksArchive(name string, data []byte) bool {
	if len(data) < 4 || len(data) > maxArchiveBytes {
		return false
	}
	low := strings.ToLower(name)
	if strings.HasSuffix(low, ".tar") || strings.HasSuffix(low, ".tar.gz") || strings.HasSuffix(low, ".tgz") {
		return true
	}
	if data[0] == 'P' && data[1] == 'K' {
		return true
	}
	if data[0] == 0x1f && data[1] == 0x8b {
		return true
	}
	switch filepath.Ext(low) {
	case ".zip", ".whl", ".jar", ".gz":
		return true
	}
	return false
}

func asUTF8(data []byte) string {
	if len(data) == 0 || len(data) > maxMemberBytes || bytesContainNUL(data) {
		return ""
	}
	if !utf8.Valid(data) {
		return ""
	}
	return string(data)
}

func walkArchive(data []byte, name string, depth int) [][2]string {
	if depth > maxArchiveDepth || !looksArchive(name, data) {
		return nil
	}
	var found [][2]string
	add := func(inner string, payload []byte) {
		if len(found) >= maxMembers {
			return
		}
		label := name + "!" + inner
		if t := asUTF8(payload); t != "" {
			found = append(found, [2]string{label, t})
		} else if looksArchive(inner, payload) {
			found = append(found, walkArchive(payload, label, depth+1)...)
		}
	}

	if len(data) >= 2 && data[0] == 'P' && data[1] == 'K' {
		zr, err := zip.NewReader(bytes.NewReader(data), int64(len(data)))
		if err != nil {
			return found
		}
		for i, f := range zr.File {
			if i >= maxMembers || f.FileInfo().IsDir() || f.UncompressedSize64 > maxMemberBytes {
				continue
			}
			rc, err := f.Open()
			if err != nil {
				continue
			}
			payload, _ := io.ReadAll(io.LimitReader(rc, maxMemberBytes+1))
			rc.Close()
			add(f.Name, payload)
		}
		return found
	}

	if len(data) >= 2 && data[0] == 0x1f && data[1] == 0x8b {
		gr, err := gzip.NewReader(bytes.NewReader(data))
		if err != nil {
			return found
		}
		unpacked, err := io.ReadAll(io.LimitReader(gr, maxArchiveBytes))
		gr.Close()
		if err != nil {
			return found
		}
		if t := asUTF8(unpacked); t != "" && !looksArchive(name, unpacked) {
			found = append(found, [2]string{name + "!(decompressed)", t})
			return found
		}
		return walkArchive(unpacked, name, depth)
	}

	tr := tar.NewReader(bytes.NewReader(data))
	for i := 0; i < maxMembers; i++ {
		hdr, err := tr.Next()
		if err != nil {
			break
		}
		if !hdr.FileInfo().Mode().IsRegular() || hdr.Size > maxMemberBytes {
			continue
		}
		payload, _ := io.ReadAll(io.LimitReader(tr, maxMemberBytes+1))
		add(hdr.Name, payload)
	}
	return found
}

package scan

import (
	"os"
	"path/filepath"
	"strings"

	"github.com/umeraamir69/secsentry/internal/gitutil"
)

const (
	ignoreFile    = ".secsentryignore"
	allowlistFile = ".secsentryallow"
)

var skipDirs = map[string]bool{
	".git": true, "node_modules": true, ".venv": true, "venv": true,
	"__pycache__": true, "dist": true, "build": true,
	".mypy_cache": true, ".pytest_cache": true, ".ruff_cache": true,
	".secsentry": true,
}

type ignores struct {
	patterns []string
}

func loadPatterns(path string) []string {
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil
	}
	var out []string
	for _, line := range strings.Split(string(raw), "\n") {
		line = strings.TrimSpace(line)
		if line != "" && !strings.HasPrefix(line, "#") {
			out = append(out, line)
		}
	}
	return out
}

func loadIgnores(repo string) ignores {
	return ignores{patterns: loadPatterns(filepath.Join(repo, ignoreFile))}
}

func (ig ignores) match(rel string) bool {
	rel = strings.ReplaceAll(rel, "\\", "/")
	base := filepath.Base(rel)
	for _, pat := range ig.patterns {
		if ok, _ := filepath.Match(pat, rel); ok {
			return true
		}
		if ok, _ := filepath.Match(pat, base); ok {
			return true
		}
		if strings.HasSuffix(pat, "/") && strings.HasPrefix(rel, pat) {
			return true
		}
		if strings.Contains(rel, pat) && strings.ContainsAny(pat, "*?[") {
			continue
		}
	}
	return false
}

func loadAllowlist(repo string) []string {
	var out []string
	for _, p := range loadPatterns(filepath.Join(repo, allowlistFile)) {
		fp := strings.Fields(p)[0]
		if fp != "" {
			out = append(out, strings.ToLower(fp))
		}
	}
	return out
}

func isAllowlisted(fingerprint string, allowed []string) bool {
	fp := strings.ToLower(fingerprint)
	for _, a := range allowed {
		if a != "" && strings.HasPrefix(fp, a) {
			return true
		}
	}
	return false
}

func skippedPath(rel string) bool {
	for _, part := range strings.Split(strings.ReplaceAll(rel, "\\", "/"), "/") {
		if skipDirs[part] {
			return true
		}
	}
	return false
}

func candidatePaths(root string) []string {
	if gitutil.IsRepo(root) {
		if tracked, err := gitutil.TrackedFiles(root); err == nil && tracked != nil {
			return tracked
		}
	}
	var out []string
	_ = filepath.WalkDir(root, func(path string, d os.DirEntry, err error) error {
		if err != nil {
			return nil
		}
		rel, _ := filepath.Rel(root, path)
		if d.IsDir() {
			if skipDirs[d.Name()] {
				return filepath.SkipDir
			}
			return nil
		}
		if skippedPath(rel) {
			return nil
		}
		out = append(out, filepath.ToSlash(rel))
		return nil
	})
	return out
}

package scan

import (
	"sort"
	"time"

	"github.com/umeraamir69/secsentry/internal/model"
	"github.com/umeraamir69/secsentry/internal/rotate"
)

type Secret struct {
	Fingerprint      string          `json:"fingerprint"`
	SecretType       string          `json:"secret_type"`
	Severity         string          `json:"severity"`
	Masked           string          `json:"masked"`
	Confidence       float64         `json:"confidence"`
	Occurrences      []model.Finding `json:"occurrences"`
	FirstSeen        string          `json:"first_seen"`
	LastSeen         string          `json:"last_seen"`
	IntroducedBy     string          `json:"introduced_by"`
	IntroducedEmail  string          `json:"introduced_email"`
	IntroducedCommit string          `json:"introduced_commit"`
	StillInHead      *bool           `json:"still_in_head"`
	AgeDays          *int            `json:"age_days"`
	Rotation         string          `json:"rotation"`
	Why              []string        `json:"why"`
}

func (s Secret) Paths() []string {
	seen := map[string]bool{}
	var out []string
	for _, o := range s.Occurrences {
		if !seen[o.Path] {
			seen[o.Path] = true
			out = append(out, o.Path)
		}
	}
	return out
}

func (s Secret) OccurrenceCount() int { return len(s.Occurrences) }

func parseTS(ts string) (time.Time, bool) {
	if ts == "" {
		return time.Time{}, false
	}
	for _, layout := range []string{time.RFC3339, time.RFC3339Nano, "2006-01-02T15:04:05"} {
		if t, err := time.Parse(layout, ts); err == nil {
			return t, true
		}
	}
	return time.Time{}, false
}

func Group(findings []model.Finding) []Secret {
	byFP := map[string]*Secret{}
	order := []string{}
	for _, f := range findings {
		s, ok := byFP[f.Fingerprint]
		if !ok {
			s = &Secret{
				Fingerprint: f.Fingerprint,
				SecretType:  f.SecretType,
				Severity:    f.Severity,
				Masked:      f.Masked,
				Confidence:  f.Confidence,
				Why:         append([]string{}, f.Why...),
				Rotation:    rotate.Hint(f.SecretType),
			}
			byFP[f.Fingerprint] = s
			order = append(order, f.Fingerprint)
		}
		s.Occurrences = append(s.Occurrences, f)
		if model.Rank(f.Severity) > model.Rank(s.Severity) {
			s.Severity = f.Severity
		}
		if f.Confidence > s.Confidence {
			s.Confidence = f.Confidence
		}
		if f.StillInHead != nil && *f.StillInHead {
			t := true
			s.StillInHead = &t
		} else if s.StillInHead == nil && f.StillInHead != nil && !*f.StillInHead {
			fval := false
			s.StillInHead = &fval
		}
	}

	now := time.Now().UTC()
	out := make([]Secret, 0, len(order))
	for _, fp := range order {
		s := byFP[fp]
		type pair struct {
			f model.Finding
			t time.Time
		}
		var dated []pair
		for _, o := range s.Occurrences {
			if t, ok := parseTS(o.Timestamp); ok {
				dated = append(dated, pair{o, t})
			}
		}
		if len(dated) > 0 {
			sort.Slice(dated, func(i, j int) bool { return dated[i].t.Before(dated[j].t) })
			earliest, latest := dated[0], dated[len(dated)-1]
			s.FirstSeen = earliest.f.Timestamp
			s.LastSeen = latest.f.Timestamp
			s.IntroducedBy = earliest.f.Author
			s.IntroducedEmail = earliest.f.AuthorEmail
			s.IntroducedCommit = earliest.f.Commit
			age := int(now.Sub(earliest.t).Hours() / 24)
			if age < 0 {
				age = 0
			}
			s.AgeDays = &age
		}
		out = append(out, *s)
	}
	sort.Slice(out, func(i, j int) bool {
		ri, rj := model.Rank(out[i].Severity), model.Rank(out[j].Severity)
		if ri != rj {
			return ri > rj
		}
		if out[i].Confidence != out[j].Confidence {
			return out[i].Confidence > out[j].Confidence
		}
		return out[i].SecretType < out[j].SecretType
	})
	return out
}

package scan

import (
	"os"
	"path/filepath"
	"strings"
	"unicode/utf8"

	"github.com/umeraamir69/secsentry/internal/classify"
	"github.com/umeraamir69/secsentry/internal/detect"
	"github.com/umeraamir69/secsentry/internal/gitutil"
	"github.com/umeraamir69/secsentry/internal/model"
	"github.com/umeraamir69/secsentry/internal/verify"
)

const maxFileBytes = 1_000_000

type Report struct {
	Findings       []model.Finding
	FilesScanned   int
	BlobsScanned   int
	CommitsScanned int
	Repo           string
	Allowlisted    int
}

func (r Report) Secrets() []Secret { return Group(r.Findings) }

func (r Report) Counts() map[string]int {
	out := map[string]int{"critical": 0, "high": 0, "medium": 0, "low": 0}
	for _, s := range r.Secrets() {
		k := strings.ToLower(s.Severity)
		if _, ok := out[k]; ok {
			out[k]++
		}
	}
	return out
}

func (r Report) ShouldFail(failOn string) bool {
	threshold := model.Rank(failOn)
	if threshold == 0 {
		threshold = 3
	}
	for _, f := range r.Findings {
		if model.Rank(f.Severity) >= threshold {
			return true
		}
	}
	return false
}

type context struct {
	findings     []model.Finding
	seen         map[string]bool
	headOIDs     map[string]struct{}
	allowed      []string
	files        int
	blobs        int
	commits      int
	allowlisted  int
}

func newContext(repo string) *context {
	return &context{
		seen:    map[string]bool{},
		allowed: loadAllowlist(repo),
	}
}

func (c *context) add(f model.Finding) {
	if isAllowlisted(f.Fingerprint, c.allowed) {
		c.allowlisted++
		return
	}
	key := f.Fingerprint + "\x00" + f.Path + "\x00" + itoa(f.Line)
	if c.seen[key] {
		return
	}
	c.seen[key] = true
	c.findings = append(c.findings, f)
}

func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	var b [12]byte
	i := len(b)
	neg := n < 0
	if neg {
		n = -n
	}
	for n > 0 {
		i--
		b[i] = byte('0' + n%10)
		n /= 10
	}
	if neg {
		i--
		b[i] = '-'
	}
	return string(b[i:])
}

func findingsFromText(path, text, blobOID string) []model.Finding {
	var found []model.Finding
	seen := map[string]bool{}

	consider := func(scanText, scanPath string, extra []string, lineOver, colOver int, useOver bool) {
		for _, hit := range detect.Detect(scanText) {
			ok := verify.OK(hit.Type, hit.Secret)
			dec := classify.Classify(scanPath, hit.Type, hit.Secret, ok)
			if !dec.Keep {
				continue
			}
			line, col := hit.Line, hit.Column
			if useOver {
				line, col = lineOver, colOver
			}
			key := hit.Secret + "\x00" + scanPath + "\x00" + itoa(line)
			if seen[key] {
				continue
			}
			seen[key] = true
			okv := ok
			found = append(found, model.Finding{
				SecretType:   hit.Type,
				Severity:     hit.Severity,
				Confidence:   dec.Confidence,
				Path:         scanPath,
				Line:         line,
				Column:       col,
				Masked:       model.Mask(hit.Secret),
				Fingerprint:  model.Fingerprint(hit.Secret),
				BlobOID:      blobOID,
				StructuralOK: &okv,
				Entropy:      hit.Entropy,
				Why:          append(append([]string{}, dec.Why...), extra...),
			})
		}
	}

	consider(text, path, nil, 0, 0, false)
	for _, chunk := range iterDecoded(text) {
		tag := "decoded:" + strings.Join(chunk.Encodings, "+")
		consider(chunk.Text, path, []string{tag}, chunk.Line, chunk.Col, true)
	}
	return found
}

func asText(data []byte) string {
	if len(data) == 0 || len(data) > maxFileBytes || bytesContainNUL(data) {
		return ""
	}
	if !utf8.Valid(data) {
		return ""
	}
	return string(data)
}

func readLimited(path string, limit int) ([]byte, bool) {
	st, err := os.Stat(path)
	if err != nil || st.Size() > int64(limit) {
		return nil, false
	}
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, false
	}
	return raw, true
}

func scanWorkingTree(ctx *context, root string) {
	ig := loadIgnores(root)
	for _, rel := range candidatePaths(root) {
		if skippedPath(rel) || ig.match(rel) {
			continue
		}
		full := filepath.Join(root, rel)
		data, ok := readLimited(full, maxArchiveBytes)
		if !ok {
			data, ok = readLimited(full, maxFileBytes)
		}
		if !ok {
			continue
		}
		ctx.files++
		if looksArchive(rel, data) {
			for _, pair := range walkArchive(data, rel, 1) {
				for _, f := range findingsFromText(pair[0], pair[1], "") {
					f.Source = "working-tree"
					ctx.add(f)
				}
			}
			continue
		}
		if len(data) > maxFileBytes {
			continue
		}
		if text := asText(data); text != "" {
			for _, f := range findingsFromText(rel, text, "") {
				f.Source = "working-tree"
				ctx.add(f)
			}
		}
	}
}

func scanStaged(ctx *context, root string) {
	pairs, err := gitutil.Staged(root)
	if err != nil {
		return
	}
	for _, p := range pairs {
		ctx.files++
		for _, f := range findingsFromText(p[0], p[1], "") {
			f.Source = "staged"
			ctx.add(f)
		}
	}
}

func hitsForBlob(oid string, data []byte, name string) []model.Finding {
	var hits []model.Finding
	if text := asText(data); text != "" || (len(data) <= maxFileBytes && utf8.Valid(data) && !bytesContainNUL(data)) {
		if t := string(data); utf8.Valid(data) && !bytesContainNUL(data) && len(data) <= maxFileBytes {
			hits = append(hits, findingsFromText(name, t, oid)...)
		}
	}
	if looksArchive(name, data) {
		for _, pair := range walkArchive(data, name, 1) {
			hits = append(hits, findingsFromText(pair[0], pair[1], oid)...)
		}
	}
	return hits
}

func scanHistory(ctx *context, root string) {
	contents, refs, err := gitutil.UniqueBlobs(root)
	if err != nil {
		return
	}
	ctx.blobs += len(contents)
	commits := map[string]struct{}{}
	for _, r := range refs {
		commits[r.Commit] = struct{}{}
	}
	ctx.commits += len(commits)

	blobHits := map[string][]model.Finding{}
	for oid, data := range contents {
		blobHits[oid] = hitsForBlob(oid, data, "(blob)")
	}
	for _, ref := range refs {
		for _, f := range blobHits[ref.OID] {
			path := f.Path
			if strings.HasPrefix(path, "(blob)!") {
				path = ref.Path + "!" + strings.SplitN(path, "!", 2)[1]
			} else if path == "(blob)" {
				path = ref.Path
			}
			f.Path = path
			f.Commit = ref.Commit
			f.Author = ref.Author
			f.AuthorEmail = ref.Email
			f.Timestamp = ref.Timestamp
			f.Source = "history"
			ctx.add(f)
		}
	}
}

type Options struct {
	History  bool
	Staged   bool
	Severity string
	Types    []string
}

func Run(repo string, opt Options) (Report, error) {
	abs, err := filepath.Abs(repo)
	if err != nil {
		return Report{}, err
	}
	ctx := newContext(abs)
	if opt.Staged {
		scanStaged(ctx, abs)
	} else {
		scanWorkingTree(ctx, abs)
		if opt.History && gitutil.IsRepo(abs) {
			ctx.headOIDs = gitutil.HeadBlobOIDs(abs)
			scanHistory(ctx, abs)
			for i := range ctx.findings {
				if ctx.findings[i].BlobOID != "" {
					_, ok := ctx.headOIDs[ctx.findings[i].BlobOID]
					ctx.findings[i].StillInHead = &ok
				}
			}
		}
	}

	findings := ctx.findings
	if opt.Severity != "" {
		th := model.Rank(opt.Severity)
		var keep []model.Finding
		for _, f := range findings {
			if model.Rank(f.Severity) >= th {
				keep = append(keep, f)
			}
		}
		findings = keep
	}
	if len(opt.Types) > 0 {
		var keep []model.Finding
		for _, f := range findings {
			low := strings.ToLower(f.SecretType)
			for _, w := range opt.Types {
				if strings.Contains(low, strings.ToLower(w)) {
					keep = append(keep, f)
					break
				}
			}
		}
		findings = keep
	}
	return Report{
		Findings:       findings,
		FilesScanned:   ctx.files,
		BlobsScanned:   ctx.blobs,
		CommitsScanned: ctx.commits,
		Repo:           abs,
		Allowlisted:    ctx.allowlisted,
	}, nil
}

package report

import (
	"fmt"
	"os"
	"strings"

	"github.com/umeraamir69/secsentry/internal/scan"
)

const (
	reset = "\033[0m"
	bold  = "\033[1m"
	dim   = "\033[2m"
)

var sevColor = map[string]string{
	"critical": "\033[91m",
	"high":     "\033[93m",
	"medium":   "\033[96m",
	"low":      "\033[90m",
}

func useColor() bool {
	if os.Getenv("NO_COLOR") != "" {
		return false
	}
	st, err := os.Stdout.Stat()
	if err != nil {
		return false
	}
	return st.Mode()&os.ModeCharDevice != 0
}

func paint(text, code string, on bool) string {
	if !on {
		return text
	}
	return code + text + reset
}

func Print(rep scan.Report) {
	color := useColor()
	secrets := rep.Secrets()
	counts := rep.Counts()

	scanned := fmt.Sprintf("files=%d", rep.FilesScanned)
	if rep.CommitsScanned > 0 {
		scanned += fmt.Sprintf("  commits=%d  blobs=%d", rep.CommitsScanned, rep.BlobsScanned)
	}
	fmt.Println(paint("SecSentry", bold, color) + "  " + scanned)

	var parts []string
	for _, name := range []string{"critical", "high", "medium", "low"} {
		if n := counts[name]; n > 0 {
			parts = append(parts, fmt.Sprintf("%d %s", n, name))
		}
	}
	line := fmt.Sprintf("%d unique secret(s), %d occurrence(s)", len(secrets), len(rep.Findings))
	if len(parts) > 0 {
		line += "  —  " + strings.Join(parts, "  ")
	}
	fmt.Println(line)
	if rep.Allowlisted > 0 {
		fmt.Printf("%d finding(s) suppressed by .secsentryallow\n", rep.Allowlisted)
	}
	fmt.Println(strings.Repeat("-", 70))
	if len(secrets) == 0 {
		fmt.Println("No findings.")
		return
	}
	for _, s := range secrets {
		head := paint("["+strings.ToUpper(s.Severity)+"]", sevColor[strings.ToLower(s.Severity)], color)
		fmt.Printf("%s %s  %s  confidence=%.2f\n", head, paint(s.SecretType, bold, color), s.Masked, s.Confidence)
		limit := len(s.Occurrences)
		if limit > 10 {
			limit = 10
		}
		for _, occ := range s.Occurrences[:limit] {
			loc := fmt.Sprintf("%s:%d:%d", occ.Path, occ.Line, occ.Column)
			extra := ""
			if occ.Commit != "" {
				c := occ.Commit
				if len(c) > 8 {
					c = c[:8]
				}
				extra = "  " + c
			}
			fmt.Printf("    %s%s\n", loc, extra)
		}
		if len(s.Occurrences) > 10 {
			fmt.Printf("    … %d more occurrence(s)\n", len(s.Occurrences)-10)
		}
		if s.IntroducedBy != "" {
			when := s.FirstSeen
			if len(when) > 10 {
				when = when[:10]
			}
			age := ""
			if s.AgeDays != nil {
				age = fmt.Sprintf(", %dd ago", *s.AgeDays)
			}
			fmt.Printf("    introduced by %s on %s%s\n", s.IntroducedBy, when, age)
		}
		if s.StillInHead != nil {
			if *s.StillInHead {
				fmt.Println("    still in HEAD")
			} else {
				fmt.Println("    deleted from HEAD, still in history")
			}
		}
		if len(s.Why) > 0 {
			fmt.Println(paint("    why: "+strings.Join(s.Why, "; "), dim, color))
		}
		fmt.Println(paint("    fix: "+s.Rotation, dim, color))
		fmt.Println()
	}
}

