func e(v any) string { return html.EscapeString(fmt.Sprint(v)) }

func card(n int, label, cls string) string {
	return fmt.Sprintf(`<div class="card %s"><div class="n">%d</div><div class="l">%s</div></div>`, cls, n, e(label))
}

func occurrencesHTML(s secretJSON) string {
	occs, _ := s.Occurrences.([]any)
	// Occurrences is []model.Finding; render via typed path on Payload isn't needed —
	// we rebuild from the JSON-shaped secret we already have.
	return occsFromSecret(s)
}

func occsFromSecret(s secretJSON) string {
	type loc struct {
		Path, Commit string
		Line, Column int
	}
	var locs []loc
	switch occs := s.Occurrences.(type) {
	case []any:
		for _, raw := range occs {
			m, _ := raw.(map[string]any)
			if m == nil {
				continue
			}
			locs = append(locs, loc{
				Path:   fmt.Sprint(m["path"]),
				Commit: fmt.Sprint(m["commit"]),
				Line:   asInt(m["line"]),
				Column: asInt(m["column"]),
			})
		}
	default:
		// []model.Finding via fmt — walk using JSON round-trip in Render
	}
	_ = locs
	return renderOccs(s)
}

func asInt(v any) int {
	switch n := v.(type) {
	case int:
		return n
	case float64:
		return int(n)
	default:
		return 0
	}
}

func renderOccs(s secretJSON) string {
	// Always encode occurrences as the Finding slice we stored.
	type occ struct {
		Path   string `json:"path"`
		Line   int    `json:"line"`
		Column int    `json:"column"`
		Commit string `json:"commit"`
	}
	var list []occ
	switch v := s.Occurrences.(type) {
	default:
		// Use Paths + OccurrenceCount fallback if type is model.Finding slice
		list = extractOccs(s.Occurrences)
	}
	var b strings.Builder
	limit := len(list)
	if limit > 25 {
		limit = 25
	}
	for _, o := range list[:limit] {
		loc := fmt.Sprintf("%s:%d:%d", o.Path, o.Line, o.Column)
		suffix := ""
		if o.Commit != "" {
			c := o.Commit
			if len(c) > 8 {
				c = c[:8]
			}
			suffix = ` <span class="dim">` + e(c) + `</span>`
		}
		b.WriteString(`<span class="loc mono">` + e(loc) + suffix + `</span>`)
	}
	if extra := len(list) - 25; extra > 0 {
		b.WriteString(fmt.Sprintf(`<span class="dim">… %d more</span>`, extra))
	}
	return b.String()
}

func extractOccs(v any) []struct {
	Path   string `json:"path"`
	Line   int    `json:"line"`
	Column int    `json:"column"`
	Commit string `json:"commit"`
} {
	type occ struct {
		Path   string `json:"path"`
		Line   int    `json:"line"`
		Column int    `json:"column"`
		Commit string `json:"commit"`
	}
	// Direct Finding slice
	type finder interface {
		GetPath() string
	}
	var out []occ
	switch items := v.(type) {
	case []occ:
		return items
	default:
		// Use encoding via type assert to scan occurrences stored as findings
		if findings, ok := v.(interface{ Len() int }); ok {
			_ = findings
		}
	}
	// Fallback: json-marshal the stored value
	raw, err := jsonBytes(v)
	if err != nil {
		return out
	}
	_ = raw
	var generic []map[string]any
	if err := unmarshalJSON(raw, &generic); err != nil {
		return out
	}
	for _, m := range generic {
		out = append(out, occ{
			Path:   fmt.Sprint(m["path"]),
			Line:   asInt(m["line"]),
			Column: asInt(m["column"]),
			Commit: str(m["commit"]),
		})
	}
	return out
}

func str(v any) string {
	if v == nil {
		return ""
	}
	s := fmt.Sprint(v)
	if s == "<nil>" {
		return ""
	}
	return s
}

func secretsTable(secrets []secretJSON) string {
	if len(secrets) == 0 {
		return `<div class="empty">No secrets found.</div>`
	}
	var rows strings.Builder
	for _, s := range secrets {
		sev := strings.ToLower(s.Severity)
		state := ""
		if s.StillInHead != nil && *s.StillInHead {
			state = `<span class="tag">in HEAD</span>`
		} else if s.StillInHead != nil && !*s.StillInHead {
			state = `<span class="tag gone">history only</span>`
		}
		byline := `<span class="dim">—</span>`
		if s.IntroducedBy != "" {
			when := s.FirstSeen
			if len(when) > 10 {
				when = when[:10]
			}
			byline = e(s.IntroducedBy) + `<br><span class="dim">` + e(when) + `</span>`
		}
		rows.WriteString("<tr>")
		rows.WriteString(`<td><span class="pill ` + sev + `">` + e(sev) + `</span></td>`)
		rows.WriteString(`<td>` + e(s.SecretType) + `<br><span class="dim mono">` + e(s.Masked) + `</span></td>`)
		rows.WriteString(`<td>` + renderOccs(s) + `</td>`)
		rows.WriteString(`<td>` + byline + `</td>`)
		rows.WriteString(`<td>` + state + `</td>`)
		rows.WriteString(`<td class="dim">` + e(s.Rotation) + `</td>`)
		rows.WriteString("</tr>")
	}
	return `<table><thead><tr><th>Severity</th><th>Secret</th><th>Where it leaked</th>` +
		`<th>Introduced by</th><th>State</th><th>How to fix</th></tr></thead>` +
		`<tbody>` + rows.String() + `</tbody></table>`
}

func peopleTable(secrets []secretJSON) string {
	people := map[string][]secretJSON{}
	for _, s := range secrets {
		if s.IntroducedBy != "" {
			people[s.IntroducedBy] = append(people[s.IntroducedBy], s)
		}
	}
	if len(people) == 0 {
		return `<div class="empty">No commit authorship available. Run with <code>--history</code>.</div>`
	}
	type row struct {
		who   string
		items []secretJSON
	}
	var rows []row
	for who, items := range people {
		rows = append(rows, row{who, items})
	}
	sort.Slice(rows, func(i, j int) bool { return len(rows[i].items) > len(rows[j].items) })
	var b strings.Builder
	for _, r := range rows {
		kinds := map[string]struct{}{}
		email := ""
		for _, i := range r.items {
			kinds[i.SecretType] = struct{}{}
			if email == "" && i.IntroducedEmail != "" {
				email = i.IntroducedEmail
			}
		}
		var kindList []string
		for k := range kinds {
			kindList = append(kindList, k)
		}
		sort.Strings(kindList)
		b.WriteString("<tr>")
		b.WriteString(`<td>` + e(r.who) + `<br><span class="dim mono">` + e(email) + `</span></td>`)
		b.WriteString(fmt.Sprintf(`<td>%d</td>`, len(r.items)))
		b.WriteString(`<td class="dim">` + e(strings.Join(kindList, ", ")) + `</td>`)
		b.WriteString("</tr>")
	}
	return `<table><thead><tr><th>Author</th><th>Secrets introduced</th><th>Types</th></tr></thead>` +
		`<tbody>` + b.String() + `</tbody></table>` +
		`<p class="dim">Introduced by = author of the earliest commit containing that secret. ` +
		`It is a starting point for a conversation, not proof of fault.</p>`
}

func timelineTable(secrets []secretJSON) string {
	var dated []secretJSON
	for _, s := range secrets {
		if s.FirstSeen != "" {
			dated = append(dated, s)
		}
	}
	if len(dated) == 0 {
		return `<div class="empty">No dates available. Run with <code>--history</code>.</div>`
	}
	sort.Slice(dated, func(i, j int) bool { return dated[i].FirstSeen < dated[j].FirstSeen })
	var b strings.Builder
	for _, s := range dated {
		age := ""
		if s.AgeDays != nil {
			age = fmt.Sprintf("%d days ago", *s.AgeDays)
		}
		when := s.FirstSeen
		if len(when) > 10 {
			when = when[:10]
		}
		c := s.IntroducedCommit
		if len(c) > 8 {
			c = c[:8]
		}
		b.WriteString("<tr>")
		b.WriteString(`<td class="mono">` + e(when) + `</td>`)
		b.WriteString(`<td>` + e(s.SecretType) + ` <span class="dim mono">` + e(s.Masked) + `</span></td>`)
		b.WriteString(`<td class="dim">` + e(age) + `</td>`)
		b.WriteString(`<td class="mono dim">` + e(c) + `</td>`)
		b.WriteString("</tr>")
	}
	return `<table><thead><tr><th>First seen</th><th>Secret</th><th>Age</th><th>Commit</th></tr></thead>` +
		`<tbody>` + b.String() + `</tbody></table>`
}

func filesTable(secrets []secretJSON) string {
	counter := map[string]int{}
	for _, s := range secrets {
		for _, p := range extractOccs(s.Occurrences) {
			counter[p.Path]++
		}
	}
	if len(counter) == 0 {
		return `<div class="empty">No files affected.</div>`
	}
	type kv struct {
		path string
		n    int
	}
	var list []kv
	for p, n := range counter {
		list = append(list, kv{p, n})
	}
	sort.Slice(list, func(i, j int) bool {
		if list[i].n != list[j].n {
			return list[i].n > list[j].n
		}
		return list[i].path < list[j].path
	})
	if len(list) > 40 {
		list = list[:40]
	}
	var b strings.Builder
	for _, x := range list {
		b.WriteString(`<tr><td class="mono">` + e(x.path) + `</td><td>` + fmt.Sprint(x.n) + `</td></tr>`)
	}
	return `<table><thead><tr><th>File</th><th>Occurrences</th></tr></thead><tbody>` + b.String() + `</tbody></table>`
}

func Render(p Payload) string {
	counts := p.Counts
	if counts == nil {
		counts = map[string]int{}
	}
	generated := p.GeneratedAt
	if len(generated) > 19 {
		generated = strings.Replace(generated[:19], "T", " ", 1)
	}
	cards := card(p.SecretCount, "unique secrets", "") +
		card(p.OccurrenceCount, "occurrences", "") +
		card(counts["critical"], "critical", "crit") +
		card(counts["high"], "high", "high") +
		card(counts["medium"], "medium", "med") +
		card(counts["low"], "low", "low") +
		card(p.FilesScanned, "files scanned", "") +
		card(p.CommitsScanned, "commits scanned", "")

	return `<!doctype html>
<html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>SecSentry — ` + e(p.Repository) + `</title><style>` + css + `</style></head>
<body>
<header>
  <h1>SecSentry</h1>
  <div class="sub mono">` + e(p.Repository) + `</div>
  <div class="sub">Scanned ` + e(generated) + ` UTC · secrets are masked · no vendor APIs were contacted</div>
</header>
<main>
  <h2>Overview</h2>
  <div class="cards">` + cards + `</div>
  <h2>Secrets</h2>
  ` + secretsTable(p.Secrets) + `
  <h2>People</h2>
  ` + peopleTable(p.Secrets) + `
  <h2>Timeline</h2>
  ` + timelineTable(p.Secrets) + `
  <h2>Files</h2>
  ` + filesTable(p.Secrets) + `
</main>
<footer>` + e(p.Note) + ` · secsentry v` + e(p.Version) + `</footer>
</body></html>
`
}

package report

import "encoding/json"

func jsonBytes(v any) ([]byte, error) { return json.Marshal(v) }

func unmarshalJSON(b []byte, v any) error { return json.Unmarshal(b, v) }

package report

import (
	"encoding/json"
	"strings"

	"github.com/umeraamir69/secsentry/internal/model"
	"github.com/umeraamir69/secsentry/internal/scan"
	"github.com/umeraamir69/secsentry/internal/version"
)

func sarifLevel(severity string) string {
	switch strings.ToLower(severity) {
	case "critical", "high":
		return "error"
	case "medium":
		return "warning"
	default:
		return "note"
	}
}

func SARIF(rep scan.Report) string {
	type region struct {
		StartLine   int `json:"startLine"`
		StartColumn int `json:"startColumn,omitempty"`
	}
	type artifact struct {
		URI string `json:"uri"`
	}
	type phys struct {
		ArtifactLocation artifact `json:"artifactLocation"`
		Region           region   `json:"region"`
	}
	type location struct {
		PhysicalLocation phys `json:"physicalLocation"`
	}
	type message struct {
		Text string `json:"text"`
	}
	type result struct {
		RuleID      string            `json:"ruleId"`
		Level       string            `json:"level"`
		Message     message           `json:"message"`
		Locations   []location        `json:"locations"`
		Fingerprints map[string]string `json:"fingerprints"`
		Properties  map[string]any    `json:"properties"`
	}
	type rule struct {
		ID               string `json:"id"`
		ShortDescription message `json:"shortDescription"`
	}
	type driver struct {
		Name            string `json:"name"`
		Version         string `json:"version"`
		InformationURI  string `json:"informationUri"`
		Rules           []rule `json:"rules,omitempty"`
	}
	type run struct {
		Tool    struct{ Driver driver } `json:"tool"`
		Results []result                `json:"results"`
	}
	type doc struct {
		Version string `json:"version"`
		Schema  string `json:"$schema"`
		Runs    []run  `json:"runs"`
	}

	seenRule := map[string]bool{}
	var rules []rule
	var results []result
	for _, f := range rep.Findings {
		if !seenRule[f.SecretType] {
			seenRule[f.SecretType] = true
			rules = append(rules, rule{
				ID:               f.SecretType,
				ShortDescription: message{Text: "Possible leaked " + f.SecretType},
			})
		}
		results = append(results, result{
			RuleID:  f.SecretType,
			Level:   sarifLevel(f.Severity),
			Message: message{Text: f.SecretType + " at " + f.Path + " (masked: " + f.Masked + ")"},
			Locations: []location{{
				PhysicalLocation: phys{
					ArtifactLocation: artifact{URI: f.Path},
					Region:           region{StartLine: f.Line, StartColumn: f.Column},
				},
			}},
			Fingerprints: map[string]string{"sha256": f.Fingerprint},
			Properties: map[string]any{
				"masked":        f.Masked,
				"severity":      f.Severity,
				"confidence":    f.Confidence,
				"still_in_head": f.StillInHead,
				"source":        f.Source,
				"why":           f.Why,
			},
		})
		_ = model.Mask // keep import if unused after edits
	}

	out := doc{
		Version: "2.1.0",
		Schema:  "https://json.schemastore.org/sarif-2.1.0.json",
		Runs: []run{{
			Tool:    struct{ Driver driver }{Driver: driver{Name: "SecSentry", Version: version.Version, InformationURI: "https://github.com/umeraamir69/secsentry", Rules: rules}},
			Results: results,
		}},
	}
	b, _ := json.MarshalIndent(out, "", "  ")
	return string(b)
}

package report

import (
	"encoding/json"
	"fmt"
	"net"
	"net/http"
	"os/exec"
	"runtime"
)

const host = "127.0.0.1"

func Serve(p Payload, port int, openBrowser bool) error {
	htmlBody := []byte(Render(p))
	raw, _ := json.MarshalIndent(p, "", "  ")

	mux := http.NewServeMux()
	mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/" && r.URL.Path != "/index.html" {
			http.NotFound(w, r)
			return
		}
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		w.Header().Set("Cache-Control", "no-store")
		_, _ = w.Write(htmlBody)
	})
	mux.HandleFunc("/report.json", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json; charset=utf-8")
		w.Header().Set("Cache-Control", "no-store")
		_, _ = w.Write(raw)
	})

	ln, err := net.Listen("tcp", fmt.Sprintf("%s:%d", host, port))
	if err != nil {
		return err
	}
	url := fmt.Sprintf("http://%s", ln.Addr().String())
	fmt.Printf("SecSentry dashboard  %s\n", url)
	fmt.Println("Loopback only. Secrets are masked. Ctrl-C to stop.")
	if openBrowser {
		_ = openURL(url)
	}
	return http.Serve(ln, mux)
}

func openURL(url string) error {
	var cmd *exec.Cmd
	switch runtime.GOOS {
	case "darwin":
		cmd = exec.Command("open", url)
	case "windows":
		cmd = exec.Command("cmd", "/c", "start", url)
	default:
		cmd = exec.Command("xdg-open", url)
	}
	return cmd.Start()
}

package hooks

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

const marker = "SecSentry pre-commit"

const hook = `#!/bin/sh
# SecSentry pre-commit
# Blocks commits that stage a HIGH or CRITICAL secret.
# Bypass (logged in history, use sparingly): git commit --no-verify

secsentry scan --staged --fail-on high || {
  echo ""
  echo "SecSentry blocked this commit."
  echo "Rotate anything real, then remove it from the staged change."
  echo "Values above are masked; the file and line show you where to look."
  exit 1
}
`

func Install(repo string) error {
	path := filepath.Join(repo, ".git", "hooks", "pre-commit")
	if raw, err := os.ReadFile(path); err == nil && !strings.Contains(string(raw), marker) {
		backup := path + ".secsentry-backup"
		if err := os.WriteFile(backup, raw, 0o755); err != nil {
			return err
		}
		fmt.Printf("Existing hook backed up to %s\n", backup)
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	if err := os.WriteFile(path, []byte(hook), 0o755); err != nil {
		return err
	}
	fmt.Printf("Installed %s\n", path)
	return nil
}

func Uninstall(repo string) error {
	path := filepath.Join(repo, ".git", "hooks", "pre-commit")
	raw, err := os.ReadFile(path)
	if err != nil {
		fmt.Println("No pre-commit hook found.")
		return nil
	}
	if !strings.Contains(string(raw), marker) {
		fmt.Println("Pre-commit hook was not installed by SecSentry; leaving it alone.")
		return nil
	}
	if err := os.Remove(path); err != nil {
		return err
	}
	fmt.Printf("Removed %s\n", path)
	return nil
}

package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/umeraamir69/secsentry/internal/hooks"
	"github.com/umeraamir69/secsentry/internal/report"
	"github.com/umeraamir69/secsentry/internal/scan"
	"github.com/umeraamir69/secsentry/internal/version"
)

const usage = `secsentry — find leaked secrets in a Git working tree and its history.

Secrets are always masked. SecSentry never sends a credential to a vendor API.

Usage:
  secsentry scan [path] [flags]
  secsentry serve [path] [flags]
  secsentry install-hook [path]
  secsentry uninstall-hook [path]

Scan flags:
  --history          scan every commit (blob-deduped)
  --staged           scan git diff --cached only
  --severity LEVEL   only report at or above this severity
  --type NAME        only this detector family (repeatable)
  --format FMT       text | json | html | sarif  (default text)
  --fail-on LEVEL    exit 1 at this severity (default high)
  --output, -o PATH  write the report to this path
  --no-cache         do not write .secsentry/last-scan.json

Serve flags:
  --port N           dashboard port (default 8765)
  --no-browser       do not open a browser
`

func main() {
	os.Exit(run(os.Args[1:]))
}

func run(argv []string) int {
	if len(argv) == 0 || argv[0] == "-h" || argv[0] == "--help" {
		fmt.Fprint(os.Stderr, usage)
		return 2
	}
	if argv[0] == "--version" || argv[0] == "-version" {
		fmt.Printf("secsentry %s\n", version.Version)
		return 0
	}
	cmd := argv[0]
	args := argv[1:]
	switch cmd {
	case "scan":
		return cmdScan(args)
	case "serve":
		return cmdServe(args)
	case "install-hook":
		path := "."
		if len(args) > 0 && !strings.HasPrefix(args[0], "-") {
			path = args[0]
		}
		abs, _ := filepath.Abs(path)
		if err := hooks.Install(abs); err != nil {
			fmt.Fprintln(os.Stderr, err)
			return 1
		}
		return 0
	case "uninstall-hook":
		path := "."
		if len(args) > 0 && !strings.HasPrefix(args[0], "-") {
			path = args[0]
		}
		abs, _ := filepath.Abs(path)
		if err := hooks.Uninstall(abs); err != nil {
			fmt.Fprintln(os.Stderr, err)
			return 1
		}
		return 0
	default:
		fmt.Fprintf(os.Stderr, "unknown command %q\n\n%s", cmd, usage)
		return 2
	}
}

type scanFlags struct {
	fs       *flag.FlagSet
	history  *bool
	staged   *bool
	severity *string
	failOn   *string
	format   *string
	output   *string
	noCache  *bool
	port     *int
	noBrowse *bool
	types    *stringList
}

type stringList []string

func (s *stringList) String() string { return strings.Join(*s, ",") }
func (s *stringList) Set(v string) error {
	*s = append(*s, v)
	return nil
}

func parseScan(name string, args []string, serve bool) (scanFlags, string, error) {
	fs := flag.NewFlagSet(name, flag.ContinueOnError)
	fs.SetOutput(os.Stderr)
	f := scanFlags{
		fs:       fs,
		history:  fs.Bool("history", false, "scan every commit"),
		staged:   fs.Bool("staged", false, "scan staged files only"),
		severity: fs.String("severity", "", "minimum severity"),
		failOn:   fs.String("fail-on", "high", "exit 1 at this severity"),
		format:   fs.String("format", "text", "text|json|html|sarif"),
		output:   fs.String("output", "", "write report to path"),
		noCache:  fs.Bool("no-cache", false, "do not write last-scan.json"),
		types:    &stringList{},
	}
	fs.Var(f.types, "type", "detector family (repeatable)")
	fs.StringVar(f.output, "o", "", "write report to path")
	if serve {
		f.port = fs.Int("port", 8765, "dashboard port")
		f.noBrowse = fs.Bool("no-browser", false, "do not open a browser")
	}
	if err := fs.Parse(args); err != nil {
		return f, "", err
	}
	path := fs.Arg(0)
	if path == "" {
		path = "."
	}
	return f, path, nil
}

func doScan(f scanFlags, path string) (string, scan.Report, error) {
	abs, err := filepath.Abs(path)
	if err != nil {
		return "", scan.Report{}, err
	}
	rep, err := scan.Run(abs, scan.Options{
		History:  *f.history,
		Staged:   *f.staged,
		Severity: *f.severity,
		Types:    []string(*f.types),
	})
	return abs, rep, err
}

func formatReport(rep scan.Report, format string) string {
	switch format {
	case "json":
		return report.JSON(rep)
	case "html":
		return report.Render(report.Build(rep))
	case "sarif":
		return report.SARIF(rep)
	default:
		return ""
	}
}

func writeCache(repo string, payload report.Payload) {
	dir := filepath.Join(repo, ".secsentry")
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return
	}
	b, err := json.MarshalIndent(payload, "", "  ")
	if err != nil {
		return
	}
	_ = os.WriteFile(filepath.Join(dir, "last-scan.json"), b, 0o644)
}

func cmdScan(args []string) int {
	f, path, err := parseScan("scan", args, false)
	if err != nil {
		return 2
	}
	repo, rep, err := doScan(f, path)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		return 1
	}
	payload := report.Build(rep)
	if *f.output != "" {
		out := *f.output
		if err := os.MkdirAll(filepath.Dir(out), 0o755); err != nil {
			fmt.Fprintln(os.Stderr, err)
			return 1
		}
		body := formatReport(rep, *f.format)
		if body == "" {
			body = report.JSON(rep)
		}
		if err := os.WriteFile(out, []byte(body), 0o644); err != nil {
			fmt.Fprintln(os.Stderr, err)
			return 1
		}
		fmt.Printf("Wrote %s\n", out)
		report.Print(rep)
	} else if *f.format == "json" {
		fmt.Println(report.JSON(rep))
	} else if *f.format == "html" {
		fmt.Print(report.Render(payload))
	} else if *f.format == "sarif" {
		fmt.Println(report.SARIF(rep))
	} else {
		report.Print(rep)
	}
	if !*f.noCache && !*f.staged {
		writeCache(repo, payload)
	}
	if rep.ShouldFail(*f.failOn) {
		return 1
	}
	return 0
}

func cmdServe(args []string) int {
	f, path, err := parseScan("serve", args, true)
	if err != nil {
