func occsFromSecret(s secretJSON) string {
	type loc struct {
		Path, Commit string
		Line, Column int
	}
	var locs []loc
	switch occs := s.Occurrences.(type) {
	case []any:
		for _, raw := range occs {
			m, _ := raw.(map[string]any)
			if m == nil {
				continue
			}
			locs = append(locs, loc{
				Path:   fmt.Sprint(m["path"]),
				Commit: fmt.Sprint(m["commit"]),
				Line:   asInt(m["line"]),
				Column: asInt(m["column"]),
			})
		}
	default:
		// []model.Finding via fmt — walk using JSON round-trip in Render
	}
	_ = locs
	return renderOccs(s)
}

