    if exe is None:
        print(
            "SecSentry needs the Go binary on PATH. Install with:\n  " + _INSTALL,
            file=sys.stderr,
        )
        raise SystemExit(1)
    raise SystemExit(subprocess.run([exe, *sys.argv[1:]], env=env).returncode)

