#!/usr/bin/env node
/**
 * Spawns the Go CLI. Does not reimplement detectors.
 * Strips this wrapper's directory from PATH so `npx secsentry` does not recurse.
 */
const { spawnSync } = require("child_process");
const fs = require("fs");
const path = require("path");

const here = path.dirname(fs.realpathSync(process.argv[1]));
const env = { ...process.env };
env.PATH = (process.env.PATH || "")
  .split(path.delimiter)
  .filter((p) => {
    if (!p) return false;
    try {
      return fs.realpathSync(p) !== here;
    } catch {
      return path.resolve(p) !== here;
    }
  })
  .join(path.delimiter);

const args = process.argv.slice(2);
const r = spawnSync("secsentry", args, { stdio: "inherit", env });
if (r.error) {
  console.error(
    "SecSentry needs the Go binary on PATH. Install with:\n  go install github.com/umeraamir69/secsentry/cmd/secsentry@latest"
  );
  process.exit(1);
}
process.exit(r.status === null ? 1 : r.status);
